Q: how to stop SizableToolWindow going under windows 10 taskbar when maximised? A: <pre><code># Best Solution (use Windows API override)

Add this to your WinForms form:

protected override void WndProc(ref Message m)
{
    const int WM_GETMINMAXINFO = 0x24;

    if (m.Msg == WM_GETMINMAXINFO)
    {
        MINMAXINFO mmi = (MINMAXINFO)Marshal.PtrToStructure(m.LParam, typeof(MINMAXINFO));

        Rectangle workArea = Screen.FromHandle(this.Handle).WorkingArea;

        mmi.ptMaxPosition.x = workArea.X;
        mmi.ptMaxPosition.y = workArea.Y;
        mmi.ptMaxSize.x = workArea.Width;
        mmi.ptMaxSize.y = workArea.Height;

        Marshal.StructureToPtr(mmi, m.LParam, true);
    }

    base.WndProc(ref m);
}

# Add required structs:
[StructLayout(LayoutKind.Sequential)]
public struct POINT
{
    public int x;
    public int y;
}

[StructLayout(LayoutKind.Sequential)]
public struct MINMAXINFO
{
    public POINT ptReserved;
    public POINT ptMaxSize;
    public POINT ptMaxPosition;
    public POINT ptMinTrackSize;
    public POINT ptMaxTrackSize;
}
</code></pre>

